def tau_x_squared(x):
    if x == 1:
        return 1

    # Prime factorization of x
    factors = {}
    n = x
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1

    # Calculate tau(x^2) = product of (2*a_i + 1)
    tau = 1
    for exponent in factors.values():
        tau *= (2 * exponent + 1)
    return tau

candidates = {
    1680: "2^4 * 3^1 * 5^1 * 7^1",
    1260: "2^2 * 3^2 * 5^1 * 7^1",
    840: "2^3 * 3^1 * 5^1 * 7^1",
    1440: "2^5 * 3^2 * 5^1",
    960: "2^6 * 3^1 * 5^1"
}

results = {}
for x, factorization in candidates.items():
    tau = tau_x_squared(x)
    results[x] = tau
    print(f"x = {x} ({factorization}): tau(x^2) = {tau}")

